1154	// ════════════════════════════════════════════════════════════════════════
1155	//  SPLIT-K dW (multi-CTA tiling — the validated mamba fix). The 9 dW yield only
1156	//  ~50 output tiles → ~62% of 132 SMs idle in P2. Split-K turns each output tile
1157	//  into G work items (one per K-chunk), so the grid sees (n_dw·G) items → idle
1158	//  SMs do work. Each CTA computes a PARTIAL over its K-chunk into a per-(tile,
1159	//  chunk) scratch slot; a grid barrier; then a DETERMINISTIC ascending-chunk
1160	//  reduce sums the G partials into grad — no float atomics, fixed order, so
1161	//  parity + A/A/A bit-determinism hold (each partial is the SAME ascending-k fp32
1162	//  wgmma accumulate; Σ_chunk == full-K sum reassociated into G fp32 blocks).
1163	//  G==1 routes to the single-CTA dectc_dw_run_tile above (no scratch). Slot (gt,
1164	//  kc) at dw_part[((gt*G+kc)) * (64*kDecMaxTileN) + row*kDecMaxTileN + col].
1165	//  Decoder K varies per spec: layer dW K=T, head dW K=B (so kc_steps reads sp.K).
1166	// ════════════════════════════════════════════════════════════════════════
1167	constexpr int kDecMaxTileN = SG_TUNED_TILE_N;                       // widest dW N-tile
1168	constexpr int kDecDwTileFloats = wgs::kWgmmaAtomM * kDecMaxTileN;   // 64*N per (gt,kc) slot
1169	
1170	// COMPILE-TIME max #dW output tiles (the 9 dW have fixed Nout/Kin; decoder dims
1171	// are compile-time → constant). per layer: qkv(3d×d), attn_out(d×d), ff0(dff×d),
1172	// ff2(d×dff), N=kDecMaxTileN; + head(V×d).
1173	constexpr int kDecDwTilesPerLayer =
1174	      ((3*dec::kD + 63)/64) * ((dec::kD  + kDecMaxTileN - 1)/kDecMaxTileN)   // qkv
1175	    + ((dec::kD   + 63)/64) * ((dec::kD  + kDecMaxTileN - 1)/kDecMaxTileN)   // attn_out
1176	    + ((dec::kDff + 63)/64) * ((dec::kD  + kDecMaxTileN - 1)/kDecMaxTileN)   // ff0
1177	    + ((dec::kD   + 63)/64) * ((dec::kDff+ kDecMaxTileN - 1)/kDecMaxTileN);  // ff2
1178	constexpr int kDecDwHeadTiles =
1179	      ((dec::kVocab + 63)/64) * ((dec::kD + kDecMaxTileN - 1)/kDecMaxTileN);
1180	constexpr int kDecDwMaxTiles = dec::kLayers * kDecDwTilesPerLayer + kDecDwHeadTiles;
1181	
1182	// Split-K dW partial-scratch float count (host carves it from the workspace tail).
1183	__host__ __device__ __forceinline__ int64_t dec_dw_part_floats(int G) {
1184	    return (int64_t)kDecDwMaxTiles * G * kDecDwTileFloats;
1185	}
