566	    //                state slice == st.sam_dir; reused verbatim on the k−1 intervening
567	    //                steps where looksam_sam==0, so NO 2nd pass runs then)
568	    //      restore p = backup
569	    //    The apply tail (P3, apply_optimizer<LookSAM>) then blends g_adj=(1−α)g+α·
570	    //    sam_dir and runs AdamW — UNCHANGED. DETERMINISM: the ‖g‖ reduction is the
571	    //    IDENTICAL deterministic ascending-CTA shape as GrokAdamW's P2.5 (fixed
572	    //    contiguous per-CTA range → per-CTA partial → CTA0 ascending sum), and the
573	    //    2nd fwd+bwd+assembly reuses the SAME A/A/A-clean machinery as the first pass
574	    //    (fixed tile ownership, ascending-k reductions), so the whole phase is
575	    //    deterministic BY CONSTRUCTION. Guarded so every other opt's path is
576	    //    byte-identical (no extra barrier / work). On a NON-SAM step (looksam_sam==0)
577	    //    this whole block is skipped — st.sam_dir already holds the cached direction.
578	    //
579	    //    SuperGrok11/15 SHARE this exact SAM 2nd-backward machinery (INTEGRATION-
580	    //    OPTSTAGES §4/§5): the perturb→2nd in-kernel fwd+bwd→restore pipeline is
581	    //    IDENTICAL; only the elementwise WRITE in step (d) differs — LookSAM writes
582	    //    st.sam_dir[i] = g_sam − g, SG11/15 write st.sharpness[i] = (g_sam − g)²
583	    //    (supergrok11_sm90.cuh:246 / supergrok15_sm90.cuh:315). sharpness is then the
584	    //    2nd MLP input the P2.45 meta-net mu precompute reads. The SAM-step gate is the
585	    //    SAME st.looksam_sam host scalar (the SG sam_step cadence); on a non-SAM step
586	    //    the cached sharpness is reused verbatim. SG reuses st.rho as the perturbation
587	    //    radius (its own sam_rho), identical reduction/perturb math.
588	    if constexpr (Opt == OptId::LookSAM || Opt == OptId::SuperGrok11 ||
589	                  Opt == OptId::SuperGrok15 || Opt == OptId::SuperGrok2) {
590	        if (st.looksam_sam != 0.0f) {
591	            // (a) GLOBAL ‖g‖ over the reduced grad, deterministic (reuse the loss
592	            //     workspace as P2.5 does: loss_part[nCTA] = per-CTA Σg², loss_out[1]
593	            //     broadcasts rho_over_norm). The reduced loss is already in
594	            //     *tok.loss_out (host state), so this is free scratch.
595	            float* sq_part = loss_part;          // [nCTA] per-CTA Σ g²  (ascending reduce)
596	            float* ron_bc  = loss_out;           // [1] broadcast rho_over_norm
597	            const int64_t total = kDecTotalElems;
598	            {
599	                const int64_t base = total / nCTA, rem = total % nCTA;
600	                const int64_t e0 = (int64_t)cta * base + (cta < rem ? cta : rem);
601	                const int64_t ecnt = base + (cta < rem ? 1 : 0);
602	                float tsum = 0.0f;
603	                for (int64_t i = threadIdx.x; i < ecnt; i += blockDim.x) {
604	                    const float gv = grad[e0 + i];
605	                    tsum += gv * gv;
606	                }
607	                float* red = sm.red;
608	                red[threadIdx.x] = tsum;
609	                __syncthreads();
610	                for (int s = blockDim.x >> 1; s > 0; s >>= 1) {
611	                    if (threadIdx.x < s) red[threadIdx.x] += red[threadIdx.x + s];
612	                    __syncthreads();
613	                }
614	                if (threadIdx.x == 0) sq_part[cta] = red[0];
615	                bar.sync();   // B2.4a: all per-CTA Σg² partials complete
616	                if (cta == 0 && threadIdx.x == 0) {
617	                    double ss = 0.0;
618	                    for (int c = 0; c < nCTA; ++c) ss += (double)sq_part[c];
619	                    const float gnorm = sqrtf((float)ss);
620	                    // rho / ‖g‖ (matches bindings.cpp looksam_perturb_all). gnorm>0 in
621	                    // any real training step; guard div-by-0 → 0 (no perturb) to be safe.
622	                    *ron_bc = (gnorm > 0.0f) ? (st.rho / gnorm) : 0.0f;
623	                }
624	                bar.sync();   // B2.4b: rho_over_norm broadcast ready
625	            }
626	            const float rho_over_norm = *ron_bc;
627	            // (b) Backup + perturb p in place: p' = p + rho_over_norm·g. Grid-strided
628	            //     over the flat param vector (each element owned once → no race).
629	            {
630	                const int64_t gstride = (int64_t)blockDim.x * gridDim.x;
631	                for (int64_t i = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
632	                     i < total; i += gstride) {
633	                    sam_backup[i] = params[i];
634	                    params[i] = params[i] + rho_over_norm * grad[i];
635	                }
636	            }
637	            bar.sync();   // B2.4c: all params perturbed before the 2nd forward reads them
638	            // (c) SECOND fwd+bwd at the perturbed weights → g_sam in `sam_grad`. Mirror
639	            //     P1 + P2 EXACTLY, but: re-zero the lnvec partials (they accumulate),
640	            //     do NOT write the loss (keep the first-pass loss), and assemble into
